def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    from collections import defaultdict

    positions = defaultdict(list)
    for r in range(h):
        for c in range(w):
            if grid[r][c] != bg:
                positions[grid[r][c]].append((r, c))

    # The marker color is the non-background color whose occurrences are
    # most widely dispersed across the canvas.
    def spread(items):
        rs = [r for r, c in items]
        cs = [c for r, c in items]
        return (max(rs) - min(rs)) * (max(cs) - min(cs)) + max(rs) - min(rs) + max(cs) - min(cs)

    marker = max(positions, key=lambda color: spread(positions[color]))
    markers = positions[marker]
    shape = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
             if grid[r][c] != bg and grid[r][c] != marker]
    if not shape:
        return [row[:] for row in grid]

    top = min(r for r, c, v in shape)
    left = min(c for r, c, v in shape)
    out = [row[:] for row in grid]

    for mr, mc in markers:
        dr, dc = mr - 1 - top, mc - left
        for r, c, color in shape:
            rr, cc = r + dr, c + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    for r, c in markers:
        out[r][c] = bg
    return out
