def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]

    # The marker color is the non-background color occurring most often.
    counts = {}
    for row in grid:
        for v in row:
            if v != bg:
                counts[v] = counts.get(v, 0) + 1
    marker = max(counts, key=counts.get)

    marks = [(r, c) for r in range(h) for c in range(w)
             if grid[r][c] == marker]
    pattern = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != marker]

    if not pattern:
        return [row[:] for row in grid]

    top = min(r for r, c, v in pattern)
    left = min(c for r, c, v in pattern)
    out = [row[:] for row in grid]

    # A marker denotes the pattern's top-left corner one row above it.
    for mr, mc in marks:
        for r, c, color in pattern:
            rr = mr - 1 + (r - top)
            cc = mc + (c - left)
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color

    for r, c in marks:
        out[r][c] = bg
    return out
